 connectedCallback(){if(!this.hasAttribute('role'))this.setAttribute('role','img');if(!this.hasAttribute('aria-label'))this.setAttribute('aria-label','Securely connected');this._epoch=performance.now();this._media.addEventListener('change',this._refresh);document.addEventListener('visibilitychange',this._refresh);this._sync();}
