 attributeChangedCallback(){if(this.isConnected)this._sync();}
 _sync(){cancelAnimationFrame(this._frame);if(this._media.matches||this.hasAttribute('paused')){this._draw(0);return;}if(!document.hidden)this._frame=requestAnimationFrame(this._tick);}
 _draw(t){const m=motion(t);this.shadowRoot.getElementById('body').setAttribute('transform','translate(627 1060) scale('+m.breath+') translate(-627 -1060)');this.shadowRoot.getElementById('head').setAttribute('transform','translate('+m.x+' '+m.y+') rotate('+m.angle+' 627 670)');for(const id of ['headSheen','shoulderSheen']){const el=this.shadowRoot.getElementById(id);el.setAttribute('opacity',m.sheen);el.setAttribute('transform','translate('+m.sheenX+' 0)');}this.shadowRoot.getElementById('pearlColor').setAttribute('stop-color',m.pearl);particles(t).forEach((q,i)=>{for(const front of [false,true]){const el=this.shadowRoot.getElementById('particle'+i+(front?'Front':'Back'));el.setAttribute('transform','translate('+q.x+' '+q.y+') rotate('+q.rotation+') scale('+q.scale+')');el.setAttribute('opacity',q.front===front?q.opacity:0);}});}
